function syncState(t){
 if(!t)return;
 if(!Array.isArray(t.buildingCondition))t.buildingCondition=[];
 if(!Array.isArray(t.buildingAbandonSeasons))t.buildingAbandonSeasons=[];
 if(!Array.isArray(t.buildingRuins))t.buildingRuins=[];
 while(t.buildingCondition.length<(t.buildings||[]).length)t.buildingCondition.push(100);
 while(t.buildingAbandonSeasons.length<(t.buildings||[]).length)t.buildingAbandonSeasons.push(0);
 if(t.buildingCondition.length>t.buildings.length)t.buildingCondition.length=t.buildings.length;
 if(t.buildingAbandonSeasons.length>t.buildings.length)t.buildingAbandonSeasons.length=t.buildings.length;
 for(let i=0;i<t.buildingCondition.length;i++)if(!Number.isFinite(t.buildingCondition[i]))t.buildingCondition[i]=100;
}
function effFromCondition(q){return q>=EFFECT_FULL?1:clamp((Number(q)||0)/EFFECT_FULL,0,1);}
function effAt(t,i){syncState(t);return effFromCondition(t.buildingCondition[i]??100);}
function physical(t,type){return !!t?.buildings?.includes(type);}
function typeEff(t,type){if(!t)return 0;syncState(t);let e=0;for(let i=0;i<t.buildings.length;i++)if(t.buildings[i]===type)e=Math.max(e,effAt(t,i));return e;}
function effectiveLocalCapacity(t){if(!t)return 0;syncState(t);let n=0;for(let i=0;i<t.buildings.length;i++)n+=(NS.BUILDINGS[t.buildings[i]]?.capacity||0)*effAt(t,i);return n;}
function effectiveCaps(t){let c={food:45,wood:30,stone:25};if(!t)return c;syncState(t);for(let i=0;i<t.buildings.length;i++){const b=t.buildings[i],e=effAt(t,i),s=NS.BUILDINGS[b]?.storage||{};for(const k of STOCK){let q=s[k]||0;if(b==='warehouse'&&t._v08UrbanStorage)q*=1.15;c[k]+=q*e;}}return c;}
function tileMaintenance(t){let wood=0,stone=0,labor=0;if(!t)return{wood,stone,labor};for(const b of t.buildings||[]){const m=MAINT[b]||{wood:10,stone:3,labor:.3};wood+=(m.wood||0)*MAINT_RATE/4;stone+=(m.stone||0)*MAINT_RATE/4;labor+=m.labor||0;}return{wood,stone,labor};}
function maintenanceSummary(v,w){let total=0,inactive=0,degraded=0,sum=0;for(const id of v.territory){const t=w.map.get(id);if(!t)continue;syncState(t);for(const q of t.buildingCondition){total++;sum+=q;if(q<=0)inactive++;else if(q<EFFECT_FULL)degraded++;}}return{total,inactive,degraded,active:total-inactive,avg:total?sum/total:100,inactiveShare:total?inactive/total:0,degradedShare:total?degraded/total:0};}

NS.Tile.prototype.buildingEfficiency=function(type){return typeEff(this,type);};
NS.Tile.prototype.hasBuilding=function(type){return typeEff(this,type)>0;};
NS.Tile.prototype.hasPhysicalBuilding=function(type){return physical(this,type);};
NS.Tile.prototype.buildingConditionSummary=function(){syncState(this);if(!this.buildings.length)return{avg:100,inactive:0,degraded:0,total:0};let sum=0,inactive=0,degraded=0;for(const q of this.buildingCondition){sum+=q;if(q<=0)inactive++;else if(q<EFFECT_FULL)degraded++;}return{avg:sum/this.buildingCondition.length,inactive,degraded,total:this.buildings.length};};
NS.Tile.prototype.syncResources=function(day){const dt=Math.max(0,day-this.lastResourceDay);if(!dt)return;const rg=NS.TERRAIN[this.terrain].regen,farm=typeEff(this,'farmstead');for(const k of ['food','wood','stone','gold']){let gain=rg[k]*dt;if(k==='food'&&farm>0)gain*=1+.35*farm;this.resources[k]=Math.min(this.resourceCap[k],this.resources[k]+gain);}this.lastResourceDay=day;};

NS.V06.capsForTile=effectiveCaps;NS.settlementCaps=effectiveCaps;if(NS.V08)NS.V08.capsForTile=effectiveCaps;
NS.Village.prototype.settlementCaps=function(tileId){return effectiveCaps(this._world?.map.get(tileId));};
NS.Village.prototype.storageCaps=function(){let c={food:0,wood:0,stone:0};for(const id of this.territory){const q=effectiveCaps(this._world?.map.get(id));for(const k of STOCK)c[k]+=q[k];}return c;};
NS.Village.prototype.depositAt=function(tileId,k,amount){const t=this._world?.map.get(tileId);if(!t)return 0;t.stocks=t.stocks||{food:0,wood:0,stone:0};const cap=effectiveCaps(t)[k],room=Math.max(0,cap-(t.stocks[k]||0)),put=Math.min(room,Math.max(0,amount));t.stocks[k]=(t.stocks[k]||0)+put;return put;};
NS.Village.prototype.capacity=function(w){let n=0;for(const id of this.territory)n+=effectiveLocalCapacity(w.map.get(id));return n;};
NS.Village.prototype.buildingCount=function(w,type){let n=0;for(const id of this.territory){const t=w.map.get(id);if(!t)continue;syncState(t);for(let i=0;i<t.buildings.length;i++)if(t.buildings[i]===type&&effAt(t,i)>0)n++;}return n;};
NS.Village.prototype.warehouseCount=function(){return [...this.territory].filter(id=>typeEff(this._world?.map.get(id),'warehouse')>0).length;};
NS.Village.prototype.tradingPosts=function(){return [...this.territory].filter(id=>typeEff(this._world?.map.get(id),'trading_post')>0);};
NS.Village.prototype.bestBirthTile=function(w){const arr=[...this.territory].map(id=>({id,pop:this.tileResidents(id).filter(p=>p.alive).length,cap:effectiveLocalCapacity(w.map.get(id))})).filter(x=>x.cap>x.pop).sort((a,b)=>(b.pop/Math.max(1,b.cap))-(a.pop/Math.max(1,a.cap)));return arr[0]?.id??this.coreTileId;};
NS.Village.prototype.securityScore=function(w){const guards=this.residents.filter(p=>p.alive&&p.job==='경비'&&p.assignment!=='PIONEER'),skill=guards.reduce((s,p)=>s+p.skills.combat,0)*.10;let pal=0;for(const id of this.territory){const t=w.map.get(id);if(!t)continue;syncState(t);for(let i=0;i<t.buildings.length;i++)if(t.buildings[i]==='palisade')pal+=effAt(t,i);}return Math.round(skill+pal*5+this.territory.size*.35);};

/* Building production scales linearly below 70%; 0% means no effect. */
const harvest10=NS.Village.prototype.harvestMultiplier;
NS.Village.prototype.harvestMultiplier=function(kind,t){let m=harvest10.call(this,kind,t),farm=typeEff(t,'farmstead');if(kind==='food'&&farm>0){m/=1.10;m*=1+.10*farm;}const p=this._v11ActingPerson;if(p)m*=clamp(1+(p.happiness-50)*.0024,.88,1.12);return m;};
const act10=NS.Person.prototype.act;
NS.Person.prototype.act=function(v,w){v._v11ActingPerson=this;try{return act10.call(this,v,w);}finally{if(v._v11ActingPerson===this)v._v11ActingPerson=null;}};

/* Roads also lose efficiency gradually instead of snapping on/off. */
function roadLevel(v){return NS.V010?.roadLevel?NS.V010.roadLevel(v):(v.hasTech('ROADS')?1:0);}
function baseRoadFactor(level){return level>=1?.62:1;}
function roadFactorAt(t,w){if(!t||t.ownerId==null)return 1;const e=typeEff(t,'road');if(e<=0)return 1;const base=baseRoadFactor(roadLevel(w.villages[t.ownerId]));return NS.V034G4?.civilianRoadFactor?.(w,t,e)??(1-(1-base)*e);}
function pathSearch(w,sourceIds,targetIds,ownerId=null){const targets=new Set(targetIds),dist=new Map(),heap=[];const push=item=>{heap.push(item);let i=heap.length-1;while(i){const p=(i-1)>>1;if(heap[p][0]<=item[0])break;heap[i]=heap[p];i=p;}heap[i]=item;};const pop=()=>{if(!heap.length)return null;const root=heap[0],last=heap.pop();if(heap.length){let i=0;while(true){let l=i*2+1,r=l+1;if(l>=heap.length)break;let c=r<heap.length&&heap[r][0]<heap[l][0]?r:l;if(heap[c][0]>=last[0])break;heap[i]=heap[c];i=c;}heap[i]=last;}return root;};for(const id of sourceIds){dist.set(id,0);push([0,id,id]);}while(heap.length){const [d,id,origin]=pop();if(d!==dist.get(id))continue;if(targets.has(id))return{cost:d,sourceId:origin,targetId:id};for(const n of w.map.neighbors4(id)){if(!NS.TERRAIN[n.terrain].passable)continue;if(ownerId!=null&&n.ownerId!==ownerId)continue;const nd=d+NS.TERRAIN[n.terrain].tradeCost*roadFactorAt(n,w);if(nd<(dist.get(n.id)??Infinity)){dist.set(n.id,nd);push([nd,n.id,origin]);}}}return{cost:Infinity,sourceId:null,targetId:null};}
function roadSignature(w){if(NS.V034C1F?.inPlan(w))return NS.V034C1F.roadSignature(w,()=>w.activeVillages.map(v=>`${v.id}:${NS.V034G4?.roadTier?.(v)??roadLevel(v)}:${[...v.territory].map(id=>{const t=w.map.get(id);return typeEff(t,'road')>0?`${id}@${Math.round(typeEff(t,'road')*10)}`:'';}).filter(Boolean).join('.')}`).join('|'));return w.activeVillages.map(v=>`${v.id}:${NS.V034G4?.roadTier?.(v)??roadLevel(v)}:${[...v.territory].map(id=>{const t=w.map.get(id);return typeEff(t,'road')>0?`${id}@${Math.round(typeEff(t,'road')*10)}`:'';}).filter(Boolean).join('.')}`).join('|');}
NS.World.prototype.routeInfo=function(a,b){const A=a.tradingPosts(),B=b.tradingPosts(),range=Math.min(a.tradeRange(this),b.tradeRange(this));if(!A.length||!B.length)return{reachable:false,cost:Infinity,range,aId:a.id,bId:b.id,aTileId:null,bTileId:null,sourceTileId:null,targetTileId:null};let minMan=Infinity,minPair=[null,null];for(const x of A)for(const y of B){const md=this.map.distance(x,y);if(md<minMan){minMan=md;minPair=[x,y];}}if(minMan*.48>range)return{reachable:false,cost:minMan,range,aId:a.id,bId:b.id,aTileId:minPair[0],bTileId:minPair[1],sourceTileId:minPair[0],targetTileId:minPair[1],lowerBoundOnly:true};const key=[a.id,b.id].sort((x,y)=>x-y).join('-'),sig=`${a.id}:${A.join('.')}|${b.id}:${B.join('.')}|${roadSignature(this)}`,day=this.ordinalDay();this.tradeRouteCache=this.tradeRouteCache||{};const cached=this.tradeRouteCache[key];if(cached&&cached.sig===sig&&day-cached.day<20){const info={...cached.info,range};info.reachable=Number.isFinite(info.cost)&&info.cost<=range;return info;}const p=pathSearch(this,A,B,null),info={cost:p.cost,aTileId:p.sourceId,bTileId:p.targetId,aId:a.id,bId:b.id,range,reachable:Number.isFinite(p.cost)&&p.cost<=range,sourceTileId:p.sourceId,targetTileId:p.targetId};this.tradeRouteCache[key]={day,sig,info:{...info}};return info;};
NS.Village.prototype.internalPathCost=function(fromId,toId){const w=this._world;if(!w)return Infinity;const bucket=Math.floor(w.ordinalDay()/5);if(!w._v11InternalPathCache||w._v11InternalPathCache.bucket!==bucket)w._v11InternalPathCache={bucket,map:new Map()};const a=Math.min(fromId,toId),b=Math.max(fromId,toId),key=`${this.id}:${fromId}>${toId}:${NS.V034G4?.roadTier?.(this)??roadLevel(this)}`;if(w._v11InternalPathCache.map.has(key))return w._v11InternalPathCache.map.get(key);const cost=pathSearch(w,[fromId],[toId],this.id).cost;w._v11InternalPathCache.map.set(key,cost);return cost;};
const deal10=NS.World.prototype.dealCandidate;
NS.World.prototype.dealCandidate=function(buyer,seller,resource,route){const d=deal10.call(this,buyer,seller,resource,route);if(!d)return null;const bt=this.map.get(d.buyerTileId??d.sourceTileId),st=this.map.get(d.sellerTileId??d.targetTileId),e=Math.min(typeEff(bt,'trading_post'),typeEff(st,'trading_post'));if(e<=0)return null;if(e<1){const old=d.qty,qty=old*e;if(qty<1.5)return null;const r=qty/old;d.qty=qty;d.price*=r;d.fee*=r;d.total*=r;d.score*=r;}return d;};

/* ---------- seasonal maintenance with condition-driven effects ---------- */
function routeWithdraw(v,w,targetId,k,need,routeUse){let left=need,got=0;const local=Math.min(left,v.stockAt(targetId,k));if(local>0){got+=v.withdrawAt(targetId,k,local);left-=local;}if(left<=1e-9)return got;const donors=[...v.territory].filter(id=>id!==targetId&&v.stockAt(id,k)>0).map(id=>({id,...v.internalLogisticsCapacity(id,targetId,k,false)})).filter(x=>x.capacity>0&&Number.isFinite(x.cost)).sort((a,b)=>a.cost-b.cost);for(const d of donors){if(left<=1e-9)break;const key=`${d.id}>${targetId}:${k}`,used=routeUse[key]||0,cap=Math.max(0,d.capacity-used);if(cap<=0)continue;const q=Math.min(left,v.stockAt(d.id,k),cap);if(q<=0)continue;const took=v.withdrawAt(d.id,k,q);routeUse[key]=used+took;got+=took;left-=took;if(took>0){v.logisticsStats.moves++;const stat=k==='wood'?'woodMoved':k==='stone'?'stoneMoved':'foodMoved';v.logisticsStats[stat]=(v.logisticsStats[stat]||0)+took;}}return got;}
function ensureMaintStats(v){v.maintenanceStats=v.maintenanceStats||{};for(const [k,x] of Object.entries({seasons:0,woodSpent:0,stoneSpent:0,laborShortageSeasons:0,resourceShortageSeasons:0,inactiveEvents:0,restoredEvents:0,collapsed:0,degradedEvents:0}))if(!Number.isFinite(v.maintenanceStats[k]))v.maintenanceStats[k]=x;return v.maintenanceStats;}
function abandonFrontierIfNeeded(v,w,t,building){if(building!=='outpost'||t.id===v.coreTileId)return;const pop=v.tileResidents(t.id).filter(p=>p.alive),otherCap=effectiveLocalCapacity(t);if(pop.length>2||otherCap>=Math.max(2,pop.length))return;for(const p of pop){p.homeTileId=v.coreTileId;p.lastMoveDay=w.ordinalDay();}v.territory.delete(t.id);t.ownerId=null;t.buildings=[];t.buildingCondition=[];t.buildingAbandonSeasons=[];t.ruin={formerVillageName:v.name,day:w.ordinalDay(),reason:'abandoned-outpost'};w.map.ruinIds.add(t.id);w.log(`${v.name}의 외곽 거점 (${t.x},${t.y})이(가) 유지되지 못해 폐허가 되었습니다.`,true,'OUTPOST_RUINED',{village:v.name,tileId:t.id,residentsRelocated:pop.length});}
NS.Village.prototype.processBuildingMaintenance=function(w){const ms=ensureMaintStats(this),routeUse={};ms.seasons++;for(const id of [...this.territory]){const t=w.map.get(id);if(!t||!t.buildings?.length)continue;syncState(t);const adults=this.tileResidents(id).filter(p=>p.alive&&p.age>=16&&p.assignment!=='PIONEER').length,teens=this.tileResidents(id).filter(p=>p.alive&&p.age>=13&&p.age<16).length;let laborBudget=adults+teens*.18;const order=t.buildings.map((b,i)=>({b,i,m:MAINT[b]||{wood:10,stone:3,labor:.30,priority:50}})).sort((a,b)=>(b.m.priority||50)-(a.m.priority||50)||((t.buildingCondition[a.i]??100)-(t.buildingCondition[b.i]??100)));let laborShort=false,resourceShort=false;for(const row of order){const{b,i,m}=row,old=t.buildingCondition[i]??100,laborNeed=m.labor||.3,laborGot=Math.min(laborNeed,laborBudget);laborBudget-=laborGot;const laborRatio=laborNeed?laborGot/laborNeed:1,woodNeed=(m.wood||0)*MAINT_RATE/4,stoneNeed=(m.stone||0)*MAINT_RATE/4,woodGot=woodNeed?routeWithdraw(this,w,id,'wood',woodNeed,routeUse):0,stoneGot=stoneNeed?routeWithdraw(this,w,id,'stone',stoneNeed,routeUse):0,resourceRatio=Math.min(woodNeed?woodGot/woodNeed:1,stoneNeed?stoneGot/stoneNeed:1),ratio=clamp(Math.min(laborRatio,resourceRatio),0,1);ms.woodSpent+=woodGot;ms.stoneSpent+=stoneGot;if(laborRatio<.75)laborShort=true;if(resourceRatio<.75)resourceShort=true;let next=old;if(ratio>=.92)next=Math.min(100,old+(old<EFFECT_FULL?7:2));else next=Math.max(0,old-(1+3*(1-ratio)));t.buildingCondition[i]=next;if(next<=0)t.buildingAbandonSeasons[i]=(t.buildingAbandonSeasons[i]||0)+1;else t.buildingAbandonSeasons[i]=0;if(old>=EFFECT_FULL&&next<EFFECT_FULL){ms.degradedEvents++;w.telemetry.record('BUILDING_DEGRADED',w,{village:this.name,tileId:id,building:b,condition:+next.toFixed(1),efficiency:+effFromCondition(next).toFixed(2)});}if(old>0&&next<=0){ms.inactiveEvents++;w.telemetry.record('BUILDING_INACTIVE',w,{village:this.name,tileId:id,building:b,condition:0,laborRatio:+laborRatio.toFixed(2),resourceRatio:+resourceRatio.toFixed(2)});}if(old<EFFECT_FULL&&next>=EFFECT_FULL){ms.restoredEvents++;w.telemetry.record('BUILDING_RESTORED',w,{village:this.name,tileId:id,building:b,condition:+next.toFixed(1)});}if(old<=0&&next>0)w.telemetry.record('BUILDING_REACTIVATED',w,{village:this.name,tileId:id,building:b,condition:+next.toFixed(1)});}
 if(laborShort)ms.laborShortageSeasons++;if(resourceShort)ms.resourceShortageSeasons++;
 for(let i=t.buildings.length-1;i>=0;i--){const b=t.buildings[i],zero=t.buildingAbandonSeasons[i]||0,limit=b==='outpost'?4:12,protectedBuilding=b==='town_hall'||b==='house';if(zero>=limit&&!protectedBuilding){t.buildingRuins.push({building:b,day:w.ordinalDay(),formerCondition:0});t.buildings.splice(i,1);t.buildingCondition.splice(i,1);t.buildingAbandonSeasons.splice(i,1);ms.collapsed++;w.log(`${this.name}의 (${t.x},${t.y}) ${NS.BUILDINGS[b]?.label||b}이(가) 장기간 방치되어 폐허가 되었습니다.`,true,'BUILDING_COLLAPSED',{village:this.name,tileId:id,building:b});abandonFrontierIfNeeded(this,w,t,b);if(!this.territory.has(id))break;}}
 }};

/* ---------- timed construction ---------- */
function ensureConstruction(v){if(!Array.isArray(v.constructionProjects))v.constructionProjects=[];return v.constructionProjects;}
function constructionCost(v,type){if(type==='outpost')return{wood:v.hasTech('ARCHITECTURE')?14.4:16,stone:v.hasTech('ARCHITECTURE')?3.6:4,gold:0};return NS.V08.effectiveCost(v,type);}
function maxProjects(v){return NS.V034D2?.projectCap?.(v)??(1+(v.population()>=25)+(v.population()>=60)+(v.hasTech('ADMINISTRATION')?1:0));}
function pendingAt(v,tileId,type=null){return ensureConstruction(v).some(p=>p.tileId===tileId&&(!type||p.type===type));}
function reserveAllows(v,cost,type){const p=v.aiPlan?.reserves;if(!p||['house','outpost','palisade','road'].includes(type))return true;for(const k of STOCK){const need=cost[k]||0;if(need>0&&v[k]-need<(p[k]||0)*.60)return false;}if((cost.gold||0)>0&&!v.isEconomicBuild31F?.(type)&&v.gold-(cost.gold||0)<(p.gold||0)*.40)return false;return true;}
NS.Village.prototype.startConstruction=function(w,tileId,type,reason='AI'){const t=w.map.get(tileId),projects=ensureConstruction(this);if(!t){NS.V034D2B?.markGate?.(this,w,tileId,'NO_TILE');return false;}if(t.ownerId!==this.id){NS.V034D2B?.markGate?.(this,w,tileId,'FOREIGN_TILE');return false;}if(physical(t,type)){NS.V034D2B?.markGate?.(this,w,tileId,'ALREADY_BUILT');return false;}if(pendingAt(this,tileId,type)||pendingAt(this,tileId)){NS.V034D2B?.markGate?.(this,w,tileId,'SITE_PROJECT_PENDING');return false;}if(projects.length>=maxProjects(this)){NS.V034D2B?.markGate?.(this,w,tileId,'PROJECT_CAP');return false;}const cost=constructionCost(this,type);if(!cost){NS.V034D2B?.markGate?.(this,w,tileId,'NO_COST_DEFINITION');return false;}if(!reserveAllows(this,cost,type)){NS.V034D2B?.markGate?.(this,w,tileId,'STRATEGIC_RESERVE');return false;}if(!this.payBuild(tileId,cost)){NS.V034D2B?.markGate?.(this,w,tileId,'PAYMENT_OR_MATERIAL');return false;}const duration=CONSTRUCTION_DAYS[type]||100,project={id:`c-${this.id}-${w.ordinalDay()}-${Math.random().toString(36).slice(2,7)}`,tileId,type,startDay:w.ordinalDay(),progress:0,duration,cost,reason,lastProgressDay:w.ordinalDay(),stallDays:0};projects.push(project);w.log(`${this.name}이(가) (${t.x},${t.y}) ${NS.BUILDINGS[type]?.label||type} 공사를 시작했습니다.`,false,'BUILDING_STARTED',{village:this.name,tileId,type,duration,cost,reason});return true;};
NS.Village.prototype.progressConstruction=function(w){const projects=ensureConstruction(this);for(let i=projects.length-1;i>=0;i--){const p=projects[i],t=w.map.get(p.tileId);if(!t||t.ownerId!==this.id){w.telemetry.record('BUILDING_CANCELLED',w,{village:this.name,tileId:p.tileId,building:p.type,reason:'territory-lost'});projects.splice(i,1);continue;}if(physical(t,p.type)){projects.splice(i,1);continue;}const workers=this.tileResidents(p.tileId).filter(x=>x.alive&&x.age>=16&&x.assignment!=='PIONEER'),architects=workers.filter(x=>x.job==='건축가').length;if(!workers.length){p.stallDays=(p.stallDays||0)+1;if(p.stallDays===30)w.telemetry.record('BUILDING_STALLED',w,{village:this.name,tileId:p.tileId,building:p.type,stallDays:p.stallDays});continue;}const avgSkill=workers.reduce((a,x)=>a+(x.skills.building||0),0)/workers.length,power=clamp(.42+workers.length*.10+architects*.12+avgSkill/400,.35,1.35);p.progress+=power;p.lastProgressDay=w.ordinalDay();p.stallDays=0;if(p.progress>=p.duration){t.addBuilding(p.type);projects.splice(i,1);if(Array.isArray(t.buildingRuins)){const ri=t.buildingRuins.findIndex(r=>r.building===p.type);if(ri>=0)t.buildingRuins.splice(ri,1);}w.log(`${this.name}의 (${t.x},${t.y}) ${NS.BUILDINGS[p.type]?.label||p.type} 공사가 완료되었습니다.`,false,'BUILDING_COMPLETED',{village:this.name,tileId:p.tileId,building:p.type,duration:p.duration,elapsed:w.ordinalDay()-p.startDay,cost:p.cost,reason:p.reason});}}};
const daily10=NS.Village.prototype.dailyTick;
NS.Village.prototype.dailyTick=function(w){daily10.call(this,w);this.progressConstruction(w);};
NS.Village.prototype.buildHouse=function(w){const tiles=[...this.territory].map(id=>w.map.get(id)).filter(t=>t&&!pendingAt(this,t.id)&&this.houseCount(t.id)<this.houseLimit(t.id));if(!tiles.length)return false;tiles.sort((a,b)=>this.tileResidents(b.id).length/Math.max(1,effectiveLocalCapacity(b))-this.tileResidents(a.id).length/Math.max(1,effectiveLocalCapacity(a)));return this.startConstruction(w,tiles[0].id,'house','HOUSING_POLICY');};
