/* ---------- richer individual happiness ---------- */
function localCondition(t){if(!t||!t.buildings?.length)return 75;syncState(t);return t.buildingCondition.reduce((a,b)=>a+b,0)/t.buildingCondition.length;}
function happinessTarget(p,v,w){const t=w.map.get(p.homeTileId),shared=NS.V034D2?.housingAt?.(v,w,p.homeTileId),pop=shared?shared.population:(t?v.tileResidents(t.id).filter(x=>x.alive).length:0),cap=shared?shared.capacity:(t?effectiveLocalCapacity(t):0),housing=pop?clamp((cap-pop)/Math.max(1,pop),-1,1):0,relations=Object.values(p.relations||{}),rel=relations.length?relations.reduce((a,b)=>a+b,0)/relations.length:20;let family=0;for(const id of [p.motherId,p.fatherId])if(id){const q=v.residents.find(x=>x.id===id&&x.alive);if(q)family+=q.homeTileId===p.homeTileId?2.5:.5;}const security=clamp((v.securityScore(w)-v.threat)/25,-1,1),cond=(localCondition(t)-70)/30,employed=p.age<15||p.job!=='무직'?1:0,recentMove=w.ordinalDay()-(p.lastMoveDay||-9999)<60?-1:0;let target=52+(50-p.hunger)*.18+(p.health-60)*.10+(p.energy-55)*.07+housing*8+clamp(cond,-1,1)*5+security*3+clamp((rel-20)/20,-1,1)*4+family+employed*2+recentMove*2;if(v.foodStressProfile().criticalShare>.15)target-=5;return clamp(target,15,90);}
const metabolism10=NS.Person.prototype.metabolism;
NS.Person.prototype.metabolism=function(v,w,worked=true){metabolism10.call(this,v,w,worked);const target=happinessTarget(this,v,w);this.happinessTarget=target;this.happiness=clamp(this.happiness+(target-this.happiness)*.014,0,100);};
const attractiveness10=NS.Village.prototype.settlementAttractiveness;
NS.Village.prototype.settlementAttractiveness=function(w,t,p){let s=attractiveness10.call(this,w,t,p);const shared=NS.V034D2?.housingAt?.(this,w,t.id),pop=shared?shared.population:this.tileResidents(t.id).filter(x=>x.alive).length,cap=shared?shared.capacity:effectiveLocalCapacity(t);s+=(cap-pop)*3;if((p?.happiness||60)<45&&t.id!==p.homeTileId)s+=4;return s;};
const available10=NS.Village.prototype.availableSettlers;
NS.Village.prototype.availableSettlers=function(){const base=available10.call(this),willing=base.filter(p=>(p.happiness??60)>=32||(p.personality?.riskTolerance||0)>=72);return willing.length>=2?willing:base;};

/* ---------- AI V3 groundwork: forecast + goals + reserves ---------- */
function ensurePlan(v,w){if(!Array.isArray(v.planningHistory))v.planningHistory=[];if(!v.aiPlan)v.aiPlan={updatedDay:0,goals:[],forecast:{},reserves:{food:0,wood:0,stone:0,gold:0}};const day=w.ordinalDay(),last=v.planningHistory.at(-1);if(!last||day-last.day>=28){v.planningHistory.push({day,pop:v.population(),food:v.food,wood:v.wood,stone:v.stone,gold:v.gold,happiness:v.avgHappiness()});v.planningHistory=v.planningHistory.filter(x=>day-x.day<=150).slice(-7);}return v.aiPlan;}
function trend(v,key,w){ensurePlan(v,w);const h=v.planningHistory;if(h.length<2)return 0;const a=h[0],b=h.at(-1),dt=Math.max(1,b.day-a.day);return((b[key]||0)-(a[key]||0))/dt*120;}
NS.Village.prototype.strategicForecast=function(w){ensurePlan(this,w);const pop=this.population(),food=this.food,wood=this.wood,stone=this.stone,gold=this.gold,popDelta=trend(this,'pop',w),foodDelta=trend(this,'food',w),woodDelta=trend(this,'wood',w),stoneDelta=trend(this,'stone',w),goldDelta=trend(this,'gold',w);return{population:Math.max(0,pop+popDelta),food:Math.max(0,food+foodDelta),wood:Math.max(0,wood+woodDelta),stone:Math.max(0,stone+stoneDelta),gold:Math.max(0,gold+goldDelta),delta:{population:popDelta,food:foodDelta,wood:woodDelta,stone:stoneDelta,gold:goldDelta}};};
NS.Village.prototype.updateStrategicPlan=function(w){const plan=ensurePlan(this,w),x=this.strategicProfile(w),f=this.strategicForecast(w),maint=maintenanceSummary(this,w),pop=this.population(),cap=Math.max(1,this.capacity(w)),pendingHouse=ensureConstruction(this).filter(p=>p.type==='house').length,predOcc=f.population/Math.max(1,cap+pendingHouse*4),avgHappy=this.avgHappiness(),scores=[
 {id:'FOOD',label:'식량 안정',score:20+x.foodUrgency*80+(f.food<Math.max(40,f.population*.36*40)?28:0)},
 {id:'INFRA',label:'기반시설 복구',score:15+maint.degradedShare*45+maint.inactiveShare*110+Math.max(0,78-maint.avg)*1.1},
 {id:'HOUSING',label:'주거 확충',score:10+Math.max(0,predOcc-.76)*110},
 {id:'TIMBER',label:'목재 확보',score:10+x.woodDef*65+(f.wood<this.targetWood(w)*.8?24:0)},
 {id:'EXPAND',label:'영토 확장',score:10+Math.min(30,x.stagnantYears*1.5)+Math.max(0,x.density-3.8)*5+(NS.AIProfileCompat(this,'territorialExpansion')>.5?18:0)-maint.inactiveShare*60},
 {id:'TRADE',label:'교역망 강화',score:8+this.tradePressure(w)*34+x.reachable*3+(NS.AIProfileCompat(this,'tradeDiplomacy')>.5?20:0)},
 {id:'HAPPINESS',label:'생활 안정',score:8+Math.max(0,60-avgHappy)*3}
 ].sort((a,b)=>b.score-a.score);const annualMaint=[...this.territory].reduce((a,id)=>{const m=tileMaintenance(w.map.get(id));a.wood+=m.wood*4;a.stone+=m.stone*4;return a;},{wood:0,stone:0}),ids=new Set(scores.slice(0,3).map(g=>g.id));plan.updatedDay=w.ordinalDay();plan.goals=scores.slice(0,3).map(g=>({id:g.id,label:g.label,score:+g.score.toFixed(1)}));plan.forecast={population:+f.population.toFixed(1),food:+f.food.toFixed(1),wood:+f.wood.toFixed(1),stone:+f.stone.toFixed(1),gold:+f.gold.toFixed(1),delta:Object.fromEntries(Object.entries(f.delta).map(([k,n])=>[k,+n.toFixed(1)])),projectedHousingOccupancy:+predOcc.toFixed(3)};plan.reserves={food:+Math.max(40,pop*.36*45+(ids.has('EXPAND')?18:0)).toFixed(1),wood:+(20+annualMaint.wood*1.25+(ids.has('EXPAND')?28:0)+(ids.has('HOUSING')?18:0)).toFixed(1),stone:+(10+annualMaint.stone*1.25+(ids.has('EXPAND')?8:0)+(ids.has('HOUSING')?6:0)).toFixed(1),gold:+(ids.has('TRADE')||ids.has('TIMBER')?20:10).toFixed(1)};return plan;};
const scores10=NS.VillageBrain.prototype.baseScores;
NS.VillageBrain.prototype.baseScores=function(v,w){const s=scores10.call(this,v,w),p=v.updateStrategicPlan(w),goal=p.goals[0]?.id;if(goal==='FOOD'){s.FOOD+=16;s.TRADE+=4;}else if(goal==='INFRA')s.MAINTAIN+=20;else if(goal==='HOUSING')s.HOUSING+=24;else if(goal==='TIMBER'){s.TRADE+=17;s.MAINTAIN+=4;}else if(goal==='EXPAND')s.EXPAND+=19;else if(goal==='TRADE')s.TRADE+=18;else if(goal==='HAPPINESS'){s.MAINTAIN+=10;s.FOOD+=4;}return s;};
